namespace Ordering;

/// <summary>Applies tier, override and channel adjustments to an order subtotal.</summary>
public sealed class PricingRules
{
    public decimal ApplyAdjustments(Order order, CustomerTier tier)
    {
        var subtotal = CalculateSubtotal(order);
        if (tier == CustomerTier.Blocked)
            return 0m;

        var adjusted = ApplyTierDiscount(subtotal, tier);
        adjusted = ApplyDiscountOverride(adjusted, order.DiscountOverride);
        adjusted = ApplyHighValueDiscount(adjusted, subtotal);
        adjusted = ApplyChannelAdjustment(adjusted, order.Channel);

        return EnsureNonNegative(adjusted);
    }

    private static decimal CalculateSubtotal(Order order)
    {
        decimal subtotal = 0m;
        foreach (var line in order.Lines)
            subtotal += line.UnitPrice * line.Quantity;

        return subtotal;
    }

    private static decimal ApplyTierDiscount(decimal subtotal, CustomerTier tier) =>
        tier == CustomerTier.Wholesale ? subtotal * 0.95m : subtotal;

    private static decimal ApplyDiscountOverride(decimal amount, decimal? discountOverride) =>
        discountOverride is > 0m ? amount - discountOverride.Value : amount;

    private static decimal ApplyHighValueDiscount(decimal amount, decimal subtotal) =>
        subtotal > 500m ? amount - 10m : amount;

    private static decimal ApplyChannelAdjustment(decimal amount, OrderChannel channel) =>
        channel switch
        {
            OrderChannel.Web => amount,
            OrderChannel.Phone => amount + 2m,
            OrderChannel.Marketplace => amount * 1.02m,
            _ => amount,
        };

    private static decimal EnsureNonNegative(decimal amount) =>
        amount < 0m ? 0m : amount;
}
